const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,PARENT=process.env.PARENT_SHA,PARENT_BLOB=process.env.PARENT_BLOB,TARGET_BLOB=process.env.TARGET_BLOB,HASH=process.env.TARGET_HASH,BYTES=Number(process.env.TARGET_BYTES),assert=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
function parse(src){const ls=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<ls.length;i++){const line=ls[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
assert(sh(`git rev-parse ${PARENT}:${TARGET}`)===PARENT_BLOB,'parent blob drift');const parent=cp.execFileSync('git',['show',`${PARENT}:${TARGET}`],{encoding:'utf8'}),p=parse(parent);assert(p.declarations.length===274&&p.dead.length===1,`parent parse drift ${p.declarations.length}/${p.dead.length}`);const d=p.dead[0];assert(d.line===396,'dead line drift');assert(d.selector==='body.orders-page-shell .doke-ai-panel'&&d.property==='height','dead selector/property drift');assert(d.value==='min(88dvh, 760px)'&&d.context==='@media (max-width: 760px)','dead value/context drift');assert(d.winnerLine===412&&d.winnerValue==='min(86dvh, 720px)','winner drift');assert(!d.important&&!d.winnerImportant,'important drift');const nl=/\r?\n$/.test(parent),ls=parent.split(/\r?\n/);if(nl&&ls.at(-1)==='')ls.pop();assert(ls[d.line-1]?.trim()==='height: min(88dvh, 760px);','source mismatch');ls.splice(d.line-1,1);const rebuilt=Buffer.from(ls.join('\n')+(nl?'\n':'')),current=fs.readFileSync(TARGET);assert(rebuilt.equals(current),'independent reconstruction differs from permanent');const blob=crypto.createHash('sha1').update(Buffer.concat([Buffer.from(`blob ${current.length}\0`),current])).digest('hex');assert(blob===TARGET_BLOB,`target blob drift ${blob}`);const q=parse(current.toString('utf8'));assert(q.declarations.length===273&&q.dead.length===0,`permanent parse drift ${q.declarations.length}/${q.dead.length}`);const hash=crypto.createHash('sha256').update(current).digest('hex');assert(hash===HASH,`hash drift ${hash}`);assert(current.length===BYTES,`bytes drift ${current.length}`);console.log(`EXACT BYTE IDENTITY PASS|parent=${PARENT}|parentBlob=${PARENT_BLOB}|targetBlob=${TARGET_BLOB}|hash=${hash}|bytes=${current.length}|decl=274->273|dead=1->0|families=1|staticCascadeRows=1|identicalWinners=0|changedWinners=1|context=max760|deadLine=396|winnerLine=412`);
